// kzn-logo — single-file build (generated by tools/build-standalone.mjs)
// ---- src/core.js ----
// kzn-logo — core geometry engine. No DOM, no dependencies.
//
// Everything below is measured from the master mark in Figma
// (file "KZN Web", node 170-3040 "Logogrid"): six equal circles composed on a
// 4×4 grid of square cells.
//
// Coordinate system for generated formations:
//   · the grid CELL is the unit of length
//   · the ORIGIN is the grid center — the crosshair the mark orbits
//   · x grows right, y grows down (SVG sense)
//   · gridlines sit at integer offsets from the origin, so a true central
//     crosshair exists at any canvas size or aspect ratio
//
// The construction system, as measured from the static mark:
//   · dot radius R = 0.3875 cells — dot diameter is 0.775 of a cell, exactly.
//     Scale of dot vs. cell is what dictates closeness; it is a constant.
//   · the KERNEL dot's edge passes through the crosshair ("touches the center
//     with its side, from any angle") — its center never sits on it
//   · every other dot sits ON the grid: center on a vertical gridline, and
//     vertically either resting centered on a horizontal gridline, or hanging
//     with its top edge kissing one (the static mark uses both)
//   · no two dots ever touch
//   · distance-to-center grows strictly rank by rank — the gravity falloff
//
// The static mark itself is the sanctioned exception: it carries ~1–2px of
// hand-tuned optical slack over this skeleton (and two rank ties). It is
// therefore stored verbatim, not generated.

/** Dot radius in cell units (31/80 — measured 42.9058px on a 110.7246px cell). */
const R = 0.3875;

/**
 * The canonical static mark ("stable symbol"), exact Figma coordinates in px,
 * cropped to the tight bounding box of the six dots (this crop is the "Logo"
 * component used across the site — aspect ≈ 1.156:1).
 * Dots are in rank order: kernel (closest to center) first.
 */
const MARK = {
  viewBox: [0, 0, 307.2609, 265.7392],
  r: 42.9058,
  cell: 110.7246,
  /** grid-center of the original Logogrid frame, in this crop's coordinates */
  center: [152.2464, 111.2826],
  dots: [
    [153.6304, 156.3986], // kernel — reaching up to the crosshair
    [153.6304, 42.9058],
    [42.9058, 42.9058],
    [264.3551, 42.9058],
    [42.9058, 222.8334],
    [264.3551, 222.8334],
  ],
};

/**
 * The same mark reduced to its rational skeleton, in grid units (center
 * origin): optical slack removed, tangency exact. Used as the resting/initial
 * state of the dynamic logo so the first shuffle departs from the mark itself.
 */
const MARK_IDEAL = {
  w: 4,
  h: 4,
  r: R,
  dots: [
    [0, R], //          kernel: hangs from the crosshair, edge through center
    [0, -1 + R], //     hangs under the upper gridline, center column
    [-1, -1 + R], //    hangs under the upper gridline, left column
    [1, -1 + R], //     hangs under the upper gridline, right column
    [-1, 1], //         rests on the lower gridline, left column
    [1, 1], //          rests on the lower gridline, right column
  ],
};

/** String/number seed → uint32 (xmur3 finalizer). */
function hashSeed(seed) {
  const s = String(seed);
  let h = 1779033703 ^ s.length;
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  h = Math.imul(h ^ (h >>> 16), 2246822507);
  h = Math.imul(h ^ (h >>> 13), 3266489909);
  return (h ^= h >>> 16) >>> 0;
}

/** Deterministic PRNG (mulberry32). Same seed → same formation, everywhere. */
function rng(seed) {
  let a = hashSeed(seed);
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Tunable rules. These four knobs are deliberately exposed — they encode the
 * open design decisions; nothing is baked in. Defaults follow the measured mark.
 */
const defaults = {
  /**
   * How strictly dots sit on the grid:
   *  'construction' — the measured system: centers on vertical gridlines,
   *                   resting on or hanging under horizontal ones (discrete)
   *  'lines'        — centers may slide anywhere along any gridline
   *  'points'       — centers on the grid intersections only (most staccato)
   * The kernel is always the one continuous element: tangent to the
   * crosshair at a free angle.
   */
  placement: 'construction',
  /** Minimum edge-to-edge clearance between dots, in cells ("never touch"). */
  gap: 0.15,
  /** How far toward the canvas reach the outermost rank may sit (0..1). */
  spread: 0.85,
  /** Minimum clearance between a dot's edge and the canvas edge, in cells. */
  edge: 0.05,
  /** Minimum growth of center-distance from one rank to the next, in cells. */
  rankStep: 0.07,
  /** Dot count, kernel included. 6 is the mark; others are decorative modes. */
  count: 6,
  /** Candidate formations scored per generate() call (quality vs. cost). */
  rollouts: 48,
  /**
   * Positions to steer away from — normally the previous formation's dots,
   * so consecutive shuffles genuinely relocate instead of a far dot keeping
   * its corner seat forever. Soft penalty, not a ban.
   */
  avoid: null,
};

const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);
const len = (p) => Math.hypot(p[0], p[1]);

/** Legal center positions for non-kernel dots under the placement rule. */
function candidatePositions(limX, limY, placement, rnd) {
  const out = [];
  const vLines = [];
  const hLines = [];
  for (let i = Math.ceil(-limX); i <= Math.floor(limX); i++) vLines.push(i);
  for (let j = Math.ceil(-limY); j <= Math.floor(limY); j++) hLines.push(j);

  if (placement === 'lines') {
    // continuous slide along gridlines — resampled every call
    const PER_LINE = 7;
    for (const i of vLines)
      for (let k = 0; k < PER_LINE; k++) out.push([i, -limY + rnd() * 2 * limY]);
    for (const j of hLines)
      for (let k = 0; k < PER_LINE; k++) out.push([-limX + rnd() * 2 * limX, j]);
    return out;
  }

  for (const i of vLines) {
    for (let j = Math.ceil(-limY - R); j <= Math.floor(limY); j++) {
      if (j >= -limY) out.push([i, j]); // resting: center on the line
      if (placement === 'construction' && j + R >= -limY && j + R <= limY)
        out.push([i, j + R]); // hanging: top edge kisses the line above
    }
  }
  return out;
}

/**
 * Generate a formation for a canvas of w×h cells (short side is normally 4).
 * Deterministic for a given (w, h, seed, options).
 * Returns { w, h, r, seed, dots, lines } with dots in rank order, kernel first.
 */
function generate(w, h, seed, options = {}) {
  const o = { ...defaults, ...options };
  const rnd = rng(seed);
  const limX = w / 2 - R - o.edge;
  const limY = h / 2 - R - o.edge;

  // The kernel: edge passes through the crosshair, at any angle.
  // Its center is at distance exactly R — never on the center itself.
  const theta = rnd() * Math.PI * 2;
  const kernel = [R * Math.cos(theta), R * Math.sin(theta)];

  const minCenterDist = 2 * R + o.gap;
  const n = Math.max(1, Math.round(o.count)) - 1; // non-kernel dots

  let best = null;
  let bestScore = -Infinity;

  const avoid = Array.isArray(o.avoid) ? o.avoid : [];

  for (let roll = 0; roll < o.rollouts; roll++) {
    const cands = candidatePositions(limX, limY, o.placement, rnd);
    const stale = cands.map((c) => {
      for (const a of avoid) if (dist(c, a) < 0.3) return 0.6;
      return 0;
    });
    let maxD = 0;
    for (const c of cands) maxD = Math.max(maxD, len(c));
    const reach = Math.max(o.spread * maxD, R + n * o.rankStep + 0.01);

    const placed = [kernel];
    const used = new Set();
    let lastD = R;
    let missing = 0;
    let relaxed = 0;

    for (let m = 1; m <= n; m++) {
      const target = R + (m / n) * (reach - R); // evenly spaced gravity rings
      const pick = (step) => {
        let bi = -1;
        let bCost = Infinity;
        for (let c = 0; c < cands.length; c++) {
          if (used.has(c)) continue;
          const p = cands[c];
          const d = len(p);
          if (d < lastD + step) continue; // falloff must keep growing
          if (d < R + 1e-6) continue; //     nothing ever sits on the center
          let ok = true;
          for (const q of placed)
            if (dist(p, q) < minCenterDist) { ok = false; break; }
          if (!ok) continue;
          const cost = Math.abs(d - target) + 0.18 * rnd() + stale[c];
          if (cost < bCost) { bCost = cost; bi = c; }
        }
        return bi;
      };
      // strict growth first; where the lattice runs out of rings (e.g.
      // 'points' on a square canvas) allow same-distance ties before giving up
      let bi = pick(o.rankStep);
      if (bi === -1) {
        bi = pick(0);
        if (bi !== -1) relaxed++;
      }
      if (bi === -1) { missing++; continue; }
      used.add(bi);
      placed.push(cands[bi]);
      lastD = len(cands[bi]);
    }

    // Score: dots should surround the center (small resultant of unit
    // vectors), keep air between each other, and use the allowed reach.
    let res = [0, 0];
    let minGap = Infinity;
    for (let i = 0; i < placed.length; i++) {
      const d = len(placed[i]);
      res[0] += placed[i][0] / d;
      res[1] += placed[i][1] / d;
      for (let j = i + 1; j < placed.length; j++)
        minGap = Math.min(minGap, dist(placed[i], placed[j]) - 2 * R);
    }
    const balance = 1 - len(res) / placed.length;
    const score =
      balance +
      0.8 * Math.min(minGap, 0.5) +
      0.4 * Math.min(lastD / reach, 1) -
      0.6 * relaxed - // prefer a strictly graded falloff whenever one exists
      10 * missing;

    if (score > bestScore) {
      bestScore = score;
      best = placed;
    }
  }

  return { w, h, r: R, seed: String(seed), dots: best, lines: gridLines(w, h) };
}

/** Interior gridlines (integer offsets from center) for the overlay. */
function gridLines(w, h) {
  const v = [];
  const hh = [];
  for (let i = Math.ceil(-w / 2); i <= Math.floor(w / 2); i++)
    if (Math.abs(i) < w / 2 - 1e-9) v.push(i);
  for (let j = Math.ceil(-h / 2); j <= Math.floor(h / 2); j++)
    if (Math.abs(j) < h / 2 - 1e-9) hh.push(j);
  return { v, h: hh };
}

/**
 * Constrain a dragged dot to the mark's rules. Returns the legal position
 * nearest the pointer — or the dot's previous position when the pointer
 * asks for something illegal (dots stop at contact, nothing ever covers
 * the crosshair).
 *  · index 0 (the kernel) ORBITS: its edge stays pinned through the center,
 *    only its angle follows the pointer
 *  · other dots project onto the active placement rule ('construction'
 *    snaps between lattice seats, 'lines' slides along gridlines,
 *    'points' snaps to intersections), inside the canvas bounds
 * The rank falloff is deliberately not enforced here — dragging is the
 * user overriding the composition.
 */
function constrainDrag(formation, index, target, options = {}) {
  const o = { ...defaults, ...options };
  const { w, h, dots } = formation;
  const limX = w / 2 - R - o.edge;
  const limY = h / 2 - R - o.edge;
  const prev = dots[index].slice();
  const minD = 2 * R + o.gap;
  const clear = (p) => {
    for (let j = 0; j < dots.length; j++) {
      if (j === index) continue;
      if (dist(p, dots[j]) < minD) return false;
    }
    return true;
  };

  if (index === 0) return orbitKernel(target, prev, clear);

  const clampX = (x) => Math.max(-limX, Math.min(limX, x));
  const clampY = (y) => Math.max(-limY, Math.min(limY, y));
  const lineX = (x) =>
    Math.max(Math.ceil(-limX), Math.min(Math.floor(limX), Math.round(x)));
  const lineY = (y) =>
    Math.max(Math.ceil(-limY), Math.min(Math.floor(limY), Math.round(y)));

  let candidates;
  if (o.placement === 'points') {
    candidates = [[lineX(target[0]), lineY(target[1])]];
  } else if (o.placement === 'lines') {
    candidates = [
      [lineX(target[0]), clampY(target[1])], // stick to a vertical line
      [clampX(target[0]), lineY(target[1])], // or to a horizontal one
    ];
  } else {
    const x = lineX(target[0]);
    const rest = Math.round(target[1]);
    const hang = Math.round(target[1] - R) + R;
    candidates = [rest, hang]
      .filter((y) => y >= -limY && y <= limY)
      .map((y) => [x, y]);
  }
  candidates.sort((a, b) => dist(a, target) - dist(b, target));
  for (const p of candidates) {
    if (Math.hypot(p[0], p[1]) < R + 0.02) continue; // center is kernel's alone
    if (clear(p)) return p;
  }
  return prev;
}

/** The kernel's drag: angle follows the pointer, edge never leaves center. */
function orbitKernel(target, prev, clear) {
  const a = Math.atan2(target[1], target[0]);
  if (!Number.isFinite(a) || (target[0] === 0 && target[1] === 0)) return prev;
  for (let k = 0; k <= 180; k++) {
    for (const s of k === 0 ? [1] : [1, -1]) {
      const ang = a + (s * k * Math.PI) / 180;
      const p = [R * Math.cos(ang), R * Math.sin(ang)];
      if (clear(p)) return p;
    }
  }
  return prev;
}

/**
 * Free drag: every dot — the kernel included — follows the pointer
 * continuously. No grid, no collision, no center ban: overlapping dots are
 * welcome (the renderer fuses them, metaball-style). The only constraint is
 * the canvas itself — dots stay on it.
 */
function freeDrag(formation, index, target, options = {}) {
  const o = { ...defaults, ...options };
  const { w, h } = formation;
  const limX = w / 2 - R - o.edge;
  const limY = h / 2 - R - o.edge;
  return [
    Math.max(-limX, Math.min(limX, target[0])),
    Math.max(-limY, Math.min(limY, target[1])),
  ];
}

/**
 * Reorder a new formation's non-kernel dots so each existing circle travels
 * the least (sum of squared moves, brute force over 5! permutations).
 * Circle 0 is the kernel and keeps its role — it only ever orbits the center.
 * Returns a new dots array aligned to the current circles' indices.
 */
function assignTargets(current, target) {
  const nk = target.length - 1;
  const idx = Array.from({ length: nk }, (_, i) => i + 1);
  let bestPerm = idx.slice();
  let bestCost = Infinity;
  const d2 = (a, b) => {
    const dx = a[0] - b[0];
    const dy = a[1] - b[1];
    return dx * dx + dy * dy;
  };
  const permute = (arr, k) => {
    if (k === arr.length) {
      let cost = 0;
      for (let i = 0; i < arr.length; i++)
        cost += d2(current[i + 1], target[arr[i]]);
      if (cost < bestCost) { bestCost = cost; bestPerm = arr.slice(); }
      return;
    }
    for (let i = k; i < arr.length; i++) {
      [arr[k], arr[i]] = [arr[i], arr[k]];
      permute(arr, k + 1);
      [arr[k], arr[i]] = [arr[i], arr[k]];
    }
  };
  if (current && current.length === target.length && nk > 0) permute(idx.slice(), 0);
  const out = [target[0]];
  for (const p of bestPerm) out.push(target[p]);
  return out;
}

// ---- src/motion.js ----
// kzn-logo — shared motion math. Pure functions, no DOM: both the SVG and
// WebGL renderers move dots through exactly these paths.
//
// Two rules carry over from the mark's concept into motion itself:
//   · the kernel never leaves the crosshair — it orbits it, edge always in
//     contact, along the shorter arc
//   · no dot ever covers the center, even mid-flight — a straight path that
//     would sweep the crosshair bows around it instead


const EASINGS = {
  cubic: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
  quint: (t) => (t < 0.5 ? 16 * t ** 5 : 1 - Math.pow(-2 * t + 2, 5) / 2),
  linear: (t) => t,
};

/** Orbit path for the kernel: angle lerps along the shorter arc, radius R→R. */
function kernelPath(a, b) {
  const a0 = Math.atan2(a[1], a[0]);
  let da = Math.atan2(b[1], b[0]) - a0;
  if (da > Math.PI) da -= 2 * Math.PI;
  if (da < -Math.PI) da += 2 * Math.PI;
  const r0 = Math.hypot(a[0], a[1]) || R;
  const r1 = Math.hypot(b[0], b[1]) || R;
  return (t) => {
    const ang = a0 + da * t;
    const rr = r0 + (r1 - r0) * t;
    return [rr * Math.cos(ang), rr * Math.sin(ang)];
  };
}

/** Straight path — bowed around the crosshair when it would sweep it. */
function dotPath(a, b) {
  const clearance = R + 0.1;
  const near = segNearestToOrigin(a, b);
  const nl = Math.hypot(near[0], near[1]);
  if (nl >= clearance) {
    return (t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  }
  // push the control point along the origin→segment shortest vector — that is
  // perpendicular to the travel, so the curve actually swerves sideways
  let dx = near[0];
  let dy = near[1];
  let dl = nl;
  if (dl < 1e-4) {
    dx = -(b[1] - a[1]);
    dy = b[0] - a[0];
    dl = Math.hypot(dx, dy) || 1;
  }
  const push = 2 * clearance + R; // control point far enough to clear center
  const cx = (dx / dl) * push;
  const cy = (dy / dl) * push;
  return (t) => {
    const u = 1 - t;
    return [
      u * u * a[0] + 2 * u * t * cx + t * t * b[0],
      u * u * a[1] + 2 * u * t * cy + t * t * b[1],
    ];
  };
}

function segNearestToOrigin(a, b) {
  const abx = b[0] - a[0];
  const aby = b[1] - a[1];
  const l2 = abx * abx + aby * aby;
  if (l2 < 1e-12) return [a[0], a[1]];
  let t = -(a[0] * abx + a[1] * aby) / l2;
  t = Math.max(0, Math.min(1, t));
  return [a[0] + t * abx, a[1] + t * aby];
}

/**
 * Build per-dot tweens from current positions to targets (index 0 = kernel).
 * `now` is the caller's clock so renderers stay testable.
 */
function buildTweens(current, targets, { duration, stagger }, now) {
  return targets.map((to, i) => {
    const from = current[i] ?? to;
    const path = i === 0 ? kernelPath(from, to) : dotPath(from, to);
    return {
      path,
      t0: now + (i === 0 ? 0 : i * stagger),
      dur: duration,
      done: false,
    };
  });
}

/**
 * Sample all tweens at `now`. Returns { pts, live }: positions per dot and
 * whether anything is still in flight. Marks finished tweens done.
 */
function sampleTweens(anims, now, easing) {
  const ease = EASINGS[easing] || EASINGS.cubic;
  const pts = new Array(anims.length);
  let live = false;
  for (let i = 0; i < anims.length; i++) {
    const a = anims[i];
    let t = (now - a.t0) / a.dur;
    if (t < 1) live = true;
    else {
      t = 1;
      a.done = true;
    }
    pts[i] = a.path(t <= 0 ? 0 : ease(t));
  }
  return { pts, live };
}

// ---- src/svg.js ----
// kzn-logo — flat SVG renderer + animator. No dependencies.
//
// Renders formations from core.js as plain <circle> elements (the dot IS a
// mathematical circle — generating it keeps geometry as data, stays crisp at
// any scale and DPR, and the same data feeds the WebGL treatment).
// Fill is `currentColor`, so the consumer sets the ink with CSS `color`.



const SVG_NS = 'http://www.w3.org/2000/svg';

/** Render the canonical static mark into an <svg> element. */
function renderMark(svg) {
  const [x, y, w, h] = MARK.viewBox;
  svg.setAttribute('viewBox', `${x} ${y} ${w} ${h}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  svg.textContent = '';
  for (const [cx, cy] of MARK.dots) {
    const c = document.createElementNS(SVG_NS, 'circle');
    c.setAttribute('cx', cx);
    c.setAttribute('cy', cy);
    c.setAttribute('r', MARK.r);
    c.setAttribute('fill', 'currentColor');
    svg.appendChild(c);
  }
}

/** Standalone SVG markup for export/download (static mark or a formation). */
function toSVG(formationOrMark, { ink = '#1E1E1E', size = 640 } = {}) {
  let vb, r, dots;
  if (formationOrMark.viewBox) {
    const m = formationOrMark;
    vb = m.viewBox;
    r = m.r;
    dots = m.dots;
  } else {
    const f = formationOrMark;
    vb = [-f.w / 2, -f.h / 2, f.w, f.h];
    r = f.r;
    dots = f.dots;
  }
  const [x, y, w, h] = vb;
  const height = Math.round((size * h) / w);
  const circles = dots
    .map(([cx, cy]) => `  <circle cx="${fmt(cx)}" cy="${fmt(cy)}" r="${fmt(r)}" fill="${ink}"/>`)
    .join('\n');
  return `<svg xmlns="${SVG_NS}" viewBox="${fmt(x)} ${fmt(y)} ${fmt(w)} ${fmt(h)}" width="${size}" height="${height}">\n${circles}\n</svg>\n`;
}

const fmt = (n) => (Math.round(n * 10000) / 10000).toString();

let softCounter = 0;

/**
 * Dynamic renderer. Owns the circles + the construction-grid overlay inside
 * one <svg>, and animates between formations at display refresh rate.
 * All motion is a single rAF loop mutating cx/cy — a handful of circles,
 * no layout work, no framework.
 */
function createDynamicRenderer(svg, opts = {}) {
  const state = {
    duration: opts.duration ?? 750,
    stagger: opts.stagger ?? 45,
    easing: opts.easing ?? 'cubic',
    motion: opts.motion ?? 'glide', // 'glide' | 'instant'
    reduced:
      typeof matchMedia === 'function' &&
      matchMedia('(prefers-reduced-motion: reduce)').matches,
    formation: null,
    circles: [],
    current: [], // live [x, y] per circle
    anims: null,
    raf: 0,
    onSettle: null,
  };

  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  const gridG = document.createElementNS(SVG_NS, 'g');
  gridG.setAttribute('stroke', 'currentColor');
  gridG.setAttribute('stroke-opacity', '0.18');
  gridG.setAttribute('display', 'none');
  const dotsG = document.createElementNS(SVG_NS, 'g');
  dotsG.setAttribute('fill', 'currentColor'); // circles inherit — appearance retints the group
  svg.append(gridG, dotsG);

  const softId = `kzn-soft-${++softCounter}`;
  let softFe = null;

  function ensureSoftFilter() {
    if (softFe) return;
    const defs = document.createElementNS(SVG_NS, 'defs');
    const filter = document.createElementNS(SVG_NS, 'filter');
    filter.setAttribute('id', softId);
    for (const [k, v] of [['x', '-60%'], ['y', '-60%'], ['width', '220%'], ['height', '220%']])
      filter.setAttribute(k, v);
    softFe = document.createElementNS(SVG_NS, 'feGaussianBlur');
    filter.appendChild(softFe);
    defs.appendChild(filter);
    svg.prepend(defs);
  }

  function ensureCircles(n) {
    while (state.circles.length < n) {
      const c = document.createElementNS(SVG_NS, 'circle');
      dotsG.appendChild(c);
      state.circles.push(c);
    }
    while (state.circles.length > n) state.circles.pop().remove();
  }

  function drawGrid(f, vw, vh) {
    gridG.textContent = '';
    const strokeW = Math.max(vw, vh) / 420; // hairline at any scale
    gridG.setAttribute('stroke-width', strokeW);
    const line = (x1, y1, x2, y2) => {
      const l = document.createElementNS(SVG_NS, 'line');
      l.setAttribute('x1', x1);
      l.setAttribute('y1', y1);
      l.setAttribute('x2', x2);
      l.setAttribute('y2', y2);
      gridG.appendChild(l);
    };
    for (const i of f.lines.v) line(i, -vh / 2, i, vh / 2);
    for (const j of f.lines.h) line(-vw / 2, j, vw / 2, j);
    // the crosshair itself, slightly more present
    const cross = document.createElementNS(SVG_NS, 'circle');
    cross.setAttribute('r', strokeW * 2.4);
    cross.setAttribute('cx', 0);
    cross.setAttribute('cy', 0);
    cross.setAttribute('fill', 'currentColor');
    cross.setAttribute('fill-opacity', '0.5');
    cross.setAttribute('stroke', 'none');
    gridG.appendChild(cross);
  }

  function put(i, x, y) {
    state.current[i] = [x, y];
    const c = state.circles[i];
    c.setAttribute('cx', x);
    c.setAttribute('cy', y);
  }

  function tick(now) {
    state.raf = 0;
    if (!state.anims) return;
    const { pts, live } = sampleTweens(state.anims, now, state.easing);
    pts.forEach(([x, y], i) => put(i, x, y));
    if (live) state.raf = requestAnimationFrame(tick);
    else {
      state.anims = null;
      state.onSettle?.();
    }
  }

  return {
    /** Move to a formation. Animates from wherever the dots are right now. */
    setFormation(f, { animate = true } = {}) {
      const first = !state.formation;
      state.formation = f;
      const [vw, vh] = f.view || [f.w, f.h];
      svg.setAttribute('viewBox', `${-vw / 2} ${-vh / 2} ${vw} ${vh}`);
      drawGrid(f, vw, vh);
      ensureCircles(f.dots.length);
      for (const c of state.circles) c.setAttribute('r', f.r);

      const instant =
        first ||
        !animate ||
        state.reduced ||
        state.motion === 'instant' ||
        state.duration <= 0;

      const targets = first ? f.dots : assignTargets(state.current, f.dots);

      if (instant) {
        if (state.raf) cancelAnimationFrame(state.raf);
        state.anims = null;
        targets.forEach(([x, y], i) => put(i, x, y));
        state.onSettle?.();
        return;
      }

      state.anims = buildTweens(state.current, targets, state, performance.now());
      if (!state.raf) state.raf = requestAnimationFrame(tick);
    },
    showGrid(on) {
      gridG.setAttribute('display', on ? 'inline' : 'none');
    },
    configure(patch) {
      Object.assign(state, patch);
    },
    resizePx() {}, // SVG scales by itself
    /** Set positions immediately (dragging) — cancels any running tween. */
    poke(dots) {
      if (state.raf) cancelAnimationFrame(state.raf);
      state.raf = 0;
      state.anims = null;
      dots.forEach(([x, y], i) => put(i, x, y));
    },
    /** Dot layer look: { ink, opacity, blend, soft } (soft in cell units). */
    setAppearance({ ink, opacity, blend, soft } = {}) {
      dotsG.setAttribute('fill', ink || 'currentColor');
      dotsG.setAttribute('fill-opacity', opacity ?? 1);
      dotsG.style.mixBlendMode = blend && blend !== 'normal' ? blend : '';
      if (soft > 0) {
        ensureSoftFilter();
        softFe.setAttribute('stdDeviation', soft / 2);
        dotsG.setAttribute('filter', `url(#${softId})`);
      } else {
        dotsG.removeAttribute('filter');
      }
    },
    get current() {
      return state.current.map((p) => p.slice());
    },
    get formation() {
      return state.formation;
    },
    get settled() {
      return !state.anims;
    },
    set onSettle(fn) {
      state.onSettle = fn;
    },
    destroy() {
      if (state.raf) cancelAnimationFrame(state.raf);
      svg.textContent = '';
    },
  };
}

// ---- src/webgl.js ----
// kzn-logo — WebGL2 renderer. Same contract as the SVG dynamic renderer,
// same formations, same motion math — plus the treated look for page
// backgrounds and hero moments.
//
// With every effect at 0 the output is pixel-parity with the flat SVG:
// antialiased currentColor dots on transparency, straight to screen.
//
// The treatment chain replicates, behaviorally, the Unicorn Studio
// prototype (project "Copy of kzn B&W"): fog → bokeh → god rays → zoom
// blur → diffuse. Parameter values (radii, speeds, centers, decay, grain)
// were extracted from that scene's data; the GLSL below is an original
// clean-room implementation of these standard techniques — no Unicorn
// Studio shader code is copied. The signature of the stack: the center
// stays sharp while the field dissolves toward the edges — gravity,
// rendered as optics.
//
// Perf posture: fragment SDF scene over ≤8 dots, quarter/half-resolution
// blur buffers, DPR capped at 2, renders continuously only while the fog
// drifts or a tween runs (reduced-motion freezes the drift).



const VS = `#version 300 es
void main() {
  vec2 v = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(v * 2.0 - 1.0, 0.0, 1.0);
}`;

const LIB = `
  const float PI = 3.14159265359;
  float ign(vec2 px) { // interleaved gradient noise (standard formula)
    return fract(52.9829189 * fract(dot(px, vec2(0.06711056, 0.00583715))));
  }
  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 345.45));
    p += dot(p, p + 34.345);
    return fract(p.x * p.y);
  }
  vec3 aces(vec3 x) { // ACES filmic curve (Narkowicz), public domain math
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
  }
`;

// value-noise fbm — original implementation; drives the fog field.
// Time is the noise's DEPTH, not a translation: two seeded slices crossfade,
// so clouds form and dissolve in place — no sideways drift.
const FBM = `
  float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1, 0));
    float c = hash21(i + vec2(0, 1));
    float d = hash21(i + vec2(1, 1));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y) * 2.0 - 1.0;
  }
  float vslice(vec2 p, float z) {
    float fz = floor(z);
    float u = z - fz;
    u = u * u * (3.0 - 2.0 * u);
    return mix(vnoise(p + fz * 17.17), vnoise(p + (fz + 1.0) * 17.17), u);
  }
  float fbm(vec2 p, float t) {
    mat2 rot = mat2(0.6, -0.8, 0.8, 0.6);
    float n = 0.0, amp = 0.55;
    for (int i = 0; i < 5; i++) {
      n += vslice(p + float(i) * 7.31, t + float(i) * 0.37) * amp;
      p = rot * p * 1.9;
      amp *= 0.55;
    }
    return n;
  }
  // fog field: centered like the source scene, sigmoid-compressed
  float fogField(vec2 uv, float ar, float t) {
    vec2 aspect = vec2(ar, 1.0);
    float mult = 10.0 * (0.648 / ((ar + 1.0) * 0.5));
    vec2 st = (uv * aspect - vec2(0.504, 0.564) * aspect) * mult;
    float c = cos(1.0128), s = sin(1.0128);
    st = mat2(c, -s, s, c) * st;
    float n = fbm(st, t * 3.0);
    n = n / (1.0 + abs(n));
    return clamp(n * 2.0, 0.0, 1.0);
  }
`;

// dots + construction grid, drawn as one signed-distance field
const SCENE_FS = `#version 300 es
precision highp float;
uniform vec2 uRes;      // px
uniform vec2 uHalf;     // view half-size, in cells
uniform vec3 uDots[8];  // x, y (cells, center origin, y down), radius
uniform int uCount;
uniform vec4 uInk;
uniform vec4 uBg;
uniform float uMode;    // 0 transparent · 1 composite on ground · 2 coverage-on-black
uniform float uGrid;
uniform float uBgMode;      // 0 flat uBg · 1 vertical 3-stop gradient
uniform vec3 uBgStops[3];
uniform float uBgMid;       // position of the middle stop, 0..1 from the top
uniform float uInkAlpha;    // dot layer opacity (Figma comp: 0.1)
uniform int uBlend;         // 0 normal · 1 difference · 2 multiply · 3 screen
uniform float uSoft;        // edge feather in cells (≈ the comp's layer blur)
uniform float uFuse;        // metaball smoothing radius in cells — 0 = hard union
out vec4 outColor;
float smin(float a, float b, float k) { // polynomial smooth minimum
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}
vec3 bgAt(float t) { // t: 0 at the top of the canvas
  if (uBgMode < 0.5) return uBg.rgb;
  return t < uBgMid
    ? mix(uBgStops[0], uBgStops[1], t / max(uBgMid, 1e-4))
    : mix(uBgStops[1], uBgStops[2], (t - uBgMid) / max(1.0 - uBgMid, 1e-4));
}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes * 2.0 - 1.0;
  vec2 p = vec2(uv.x * uHalf.x, -uv.y * uHalf.y);
  float pxPerCell = uRes.x / (2.0 * uHalf.x);
  float aa = 1.0 / pxPerCell;

  float d = 1e5;
  for (int i = 0; i < 8; i++) {
    if (i >= uCount) break;
    float di = length(p - uDots[i].xy) - uDots[i].z;
    d = uFuse > 1e-4 ? smin(d, di, uFuse) : min(d, di);
  }
  float cov = 1.0 - smoothstep(-aa - uSoft, aa + uSoft, d);

  float gridA = 0.0;
  if (uGrid > 0.5) {
    float lw = max(uHalf.x, uHalf.y) * 2.0 / 420.0; // hairline, as in SVG
    vec2 nearest = vec2(floor(p.x + 0.5), floor(p.y + 0.5));
    vec2 dist = abs(p - nearest);
    float lx = (abs(nearest.x) <= uHalf.x - 0.001)
      ? 1.0 - smoothstep(lw * 0.5, lw * 0.5 + aa, dist.x) : 0.0;
    float ly = (abs(nearest.y) <= uHalf.y - 0.001)
      ? 1.0 - smoothstep(lw * 0.5, lw * 0.5 + aa, dist.y) : 0.0;
    float cross = (1.0 - smoothstep(lw * 2.4, lw * 2.4 + aa, length(p))) * 0.5;
    gridA = max(max(lx, ly) * 0.18, cross);
  }

  if (uMode > 1.5) {
    outColor = vec4(vec3(cov), 1.0); // pure dot light — feeds the fog
  } else if (uMode > 0.5) {
    vec3 ground = bgAt(1.0 - gl_FragCoord.y / uRes.y);
    vec3 blended = uBlend == 1 ? abs(ground - uInk.rgb)
      : uBlend == 2 ? ground * uInk.rgb
      : uBlend == 3 ? 1.0 - (1.0 - ground) * (1.0 - uInk.rgb)
      : uInk.rgb;
    vec3 col = mix(ground, blended, cov * uInkAlpha);
    outColor = vec4(mix(col, uInk.rgb, gridA), 1.0);
  } else {
    float a = cov * uInkAlpha;
    outColor = vec4(uInk.rgb * a + uInk.rgb * gridA * (1.0 - a),
                    min(1.0, a + gridA * (1.0 - a))); // premultiplied
  }
}`;

// the drifting fbm field, computed ONCE per frame at quarter res — the blur
// and composite passes sample this texture instead of re-evaluating noise
const FIELD_FS = `#version 300 es
precision highp float;
uniform vec2 uRes;
uniform float uTime;
out vec4 outColor;
${LIB}
${FBM}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float f = fogField(uv, uRes.x / uRes.y, uTime);
  outColor = vec4(f, f, f, 1.0);
}`;

// fog blur: exponential-falloff directional blur whose radius is modulated
// by the fog field (radius 1%–3% of the frame, as in the source scene)
const FOGBLUR_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform sampler2D uField;
uniform vec2 uRes;
uniform vec2 uDir;
uniform float uAmt;
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float ar = uRes.x / uRes.y;
  float f = texture(uField, uv).r;
  float radius = mix(0.01, 0.03, clamp(8.0 * f * 0.35, 0.0, 1.0)) * uAmt;
  vec2 dir = normalize(uDir) / vec2(ar, 1.0);
  vec4 acc = texture(uTex, uv);
  float total = 1.0;
  for (int i = 1; i <= 8; i++) {
    float w = exp(-float(i) / 3.0);
    float off = radius * float(i) / 8.0;
    acc += (texture(uTex, uv + off * dir) + texture(uTex, uv - off * dir)) * w;
    total += 2.0 * w;
  }
  outColor = acc / total;
}`;

// fog composite: the halo field (blurred dot coverage) is ACES-toned,
// grained, masked by the drifting fbm — then pushes pixels toward the ink.
// Clipped to the dots' own light: the background itself never fogs.
// (On the prototype's black ground this reduces to the same additive math.)
const FOGCOMP_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;   // sharp composite
uniform sampler2D uBlur;  // blurred dot coverage — the halo field
uniform sampler2D uField; // the precomputed fbm field
uniform vec2 uRes;
uniform float uTime;
uniform float uFog;
uniform float uGrain;
uniform vec4 uInk;
uniform vec4 uBg;
uniform float uBgMode;
uniform vec3 uBgStops[3];
uniform float uBgMid;
out vec4 outColor;
${LIB}
vec3 bgAt(float t) {
  if (uBgMode < 0.5) return uBg.rgb;
  return t < uBgMid
    ? mix(uBgStops[0], uBgStops[1], t / max(uBgMid, 1e-4))
    : mix(uBgStops[1], uBgStops[2], (t - uBgMid) / max(1.0 - uBgMid, 1e-4));
}
uniform float uOverlay; // 1 = transparent dot-layer pipeline (CSS owns the ground)
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec4 base = texture(uTex, uv);
  float halo = texture(uBlur, uv).r;
  float mask = texture(uField, uv).r * uFog;
  float presence = smoothstep(0.0, 0.12, halo);
  float grain = hash21(uv * uRes.xy / 100.0 + fract(uTime));
  float light = aces(vec3(halo * 0.8)).r + grain * 0.05 * uGrain;
  float L = light * mask * presence;
  if (uOverlay > 0.5) {
    // premultiplied: the fog adds the ink's own light to the dot layer;
    // compositing against the page ground happens in CSS
    outColor = vec4(base.rgb + uInk.rgb * L, min(1.0, base.a + L));
  } else {
    vec3 ground = bgAt(1.0 - uv.y);
    outColor = vec4(base.rgb + (uInk.rgb - ground) * L, 1.0);
  }
}`;

// bokeh: golden-angle disc blur, dithered by gradient noise
const BOKEH_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uAmt; // radius scale; source scene: 0.1
out vec4 outColor;
${LIB}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float ar = uRes.x / uRes.y;
  float radius = 0.1 * uAmt * 0.25;
  float rot = ign(gl_FragCoord.xy) * 2.0 * PI;
  vec4 acc = vec4(0.0);
  const int N = 16;
  for (int i = 0; i < N; i++) {
    float t = (float(i) + 0.5) / float(N);
    float a = float(i) * 2.39996323 + rot; // golden angle
    vec2 off = vec2(cos(a) / ar, sin(a)) * sqrt(t) * radius;
    acc += texture(uTex, uv + off);
  }
  outColor = acc / float(N);
}`;

// god rays: luminance-weighted samples marching toward the light, additive
const RAYS_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uAmt;
out vec4 outColor;
${LIB}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec2 light = vec2(0.5, 0.5574); // just below center, as in the source scene
  const float N = 48.0;
  vec2 stepv = (light - uv) / N * 0.2775;
  float noise = ign(gl_FragCoord.xy);
  vec2 s = uv + stepv * noise;
  vec2 perp = vec2(-stepv.y, stepv.x);
  float weight = 1.0;
  vec3 acc = vec3(0.0);
  for (float i = 0.0; i < N; i++) {
    float th = i / N;
    s += stepv + perp * th * sin(noise * 0.25 * (1.0 + th) * 50.0) * 0.15;
    vec3 samp = texture(uTex, s).rgb;
    float lum = dot(samp, vec3(0.299, 0.587, 0.114));
    acc += samp * smoothstep(-0.1, 0.0, lum) * weight;
    weight *= 0.899;
    if (weight < 0.05) break;
  }
  outColor = vec4(acc / N * 2.8 * uAmt, 1.0);
}`;

const ADD_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;  // base
uniform sampler2D uAddT; // additive layer
uniform vec2 uRes;
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec4 b = texture(uTex, uv);
  vec3 add = texture(uAddT, uv).rgb;
  float aAdd = dot(add, vec3(0.299, 0.587, 0.114));
  outColor = vec4(b.rgb + add, min(1.0, b.a + aAdd));
}`;

// zoom blur: radial streaks toward the center — gated OFF near the center
// (spread 0.23), so the crosshair region stays untouched
const ZOOM_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uAmt;
out vec4 outColor;
${LIB}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float ar = uRes.x / uRes.y;
  vec2 center = vec2(0.5012, 0.5648);
  float d = distance(uv * vec2(ar, 1.0), center * vec2(ar, 1.0));
  float near = max(0.0, 1.0 - d * 4.0 * (1.0 - 0.23));
  float gate = max(0.0, 0.5 - near * near); // zero at center, on toward edges
  vec2 toC = (center - uv) * 0.22 * uAmt * gate;
  float noise = ign(gl_FragCoord.xy);
  vec4 acc = vec4(0.0);
  const int N = 20;
  for (int i = 0; i < N; i++) {
    float t = (float(i) + noise) / float(N);
    acc += texture(uTex, uv + toC * t);
  }
  outColor = acc / float(N);
}`;

// diffuse: static random scatter, also zero at the center (tightness 0.75) —
// dots melt into the field the farther they sit from the gravity well
const DIFFUSE_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uAmt;
uniform float uDifAngle; // scatter drift direction, radians (prototype: 45°)
uniform float uDifTight; // how close to center stays sharp (prototype: 0.75)
out vec4 outColor;
${LIB}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float ar = uRes.x / uRes.y;
  float dctr = distance(uv * vec2(ar, 1.0), vec2(0.5 * ar, 0.5));
  float near = max(0.0, 1.0 - dctr * 4.0 * (1.0 - uDifTight));
  float gate = max(0.0, 0.5 - near * near);
  float amount = 1.068 * uAmt * gate;
  vec2 dir = vec2(cos(uDifAngle) / ar, sin(uDifAngle)) * 0.7071 * amount * 0.4;
  vec4 acc = vec4(0.0);
  const int N = 12;
  float used = 0.0;
  for (int i = 0; i < N; i++) {
    float t = (float(i) + 0.5) / float(N);
    if (t > 0.84) break;
    float r1 = hash21(uv + t);
    float r2 = hash21(uv + t * 2.0);
    float r3 = hash21(uv + t * 3.0);
    vec2 pt = (vec2(r1, r2) * 2.0 - 1.0) * mix(1.0, r3, 0.8);
    acc += texture(uTex, uv + pt * dir);
    used += 1.0;
  }
  outColor = used > 0.0 ? acc / used : texture(uTex, uv);
}`;

// final grade: optional duotone toward a tint (for non-B&W colorways)
const GRADE_FS = `#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uTintAmt;
uniform vec3 uTintInk;
uniform vec3 uTintBg;
out vec4 outColor;
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec4 c = texture(uTex, uv);
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  c.rgb = mix(c.rgb, mix(uTintInk, uTintBg, lum) * max(c.a, 0.0001), uTintAmt);
  outColor = c; // alpha passes through — transparent overlays stay transparent
}`;

/** '#rrggbb' | 'rgb(a)' string → [r,g,b,a] in 0..1 */
function parseColor(str) {
  if (!str) return [0, 0, 0, 1];
  str = str.trim();
  if (str[0] === '#') {
    const h = str.slice(1);
    const n = parseInt(h.length === 3 ? [...h].map((c) => c + c).join('') : h, 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255, 1];
  }
  const m = str.match(/rgba?\(([^)]+)\)/);
  if (!m) return [0, 0, 0, 1];
  const v = m[1].split(',').map(parseFloat);
  return [v[0] / 255, v[1] / 255, v[2] / 255, v.length > 3 ? v[3] : 1];
}

/** The extracted treatment defaults — the prototype's design values. */
const KAIZEN_STACK = {
  fog: 1,
  bokeh: 1,
  rays: 1,
  zoom: 1,
  diffuse: 1,
  grain: 1,
  tint: 0,
  tintColor: '#AFA8D8',
  background: null,
};

const ZERO_STACK = Object.fromEntries(
  Object.keys(KAIZEN_STACK).map((k) => [k, typeof KAIZEN_STACK[k] === 'number' ? 0 : KAIZEN_STACK[k]])
);

const BLEND_IDS = { normal: 0, difference: 1, multiply: 2, screen: 3 };

function createWebGLRenderer(canvas, host, opts = {}) {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!gl) return null;

  function compile(fsSrc) {
    const p = gl.createProgram();
    for (const [type, src] of [
      [gl.VERTEX_SHADER, VS],
      [gl.FRAGMENT_SHADER, fsSrc],
    ]) {
      const s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
        throw new Error('kzn-logo shader: ' + gl.getShaderInfoLog(s));
      gl.attachShader(p, s);
    }
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS))
      throw new Error('kzn-logo link: ' + gl.getProgramInfoLog(p));
    const uniforms = {};
    const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS);
    for (let i = 0; i < n; i++) {
      const info = gl.getActiveUniform(p, i);
      uniforms[info.name.replace(/\[0\]$/, '')] = gl.getUniformLocation(p, info.name);
    }
    return { p, u: uniforms };
  }

  const prg = {
    scene: compile(SCENE_FS),
    field: compile(FIELD_FS),
    fogBlur: compile(FOGBLUR_FS),
    fogComp: compile(FOGCOMP_FS),
    bokeh: compile(BOKEH_FS),
    rays: compile(RAYS_FS),
    add: compile(ADD_FS),
    zoom: compile(ZOOM_FS),
    diffuse: compile(DIFFUSE_FS),
    grade: compile(GRADE_FS),
  };

  const state = {
    duration: opts.duration ?? 750,
    stagger: opts.stagger ?? 45,
    easing: opts.easing ?? 'cubic',
    motion: opts.motion ?? 'glide',
    reduced:
      typeof matchMedia === 'function' &&
      matchMedia('(prefers-reduced-motion: reduce)').matches,
    formation: null,
    current: [],
    anims: null,
    raf: 0,
    gridOn: false,
    onSettle: null,
    ink: [0.12, 0.12, 0.12, 1],
    bg: [1, 0.984, 0.973, 1],
    bgGrad: null, // { mid, stops: [rgb, rgb, rgb] } when the ground is a gradient
    appearance: { ink: null, opacity: 1, blend: 'normal', soft: 0, fuse: 0 },
    effects: {
      ...ZERO_STACK,
      difAngle: 45,
      difTight: 0.75,
      fogSpeed: 0.2, //   the source layer's speed
      renderScale: 1, //  resolution factor for the whole chain
      order: null, //     pass order, e.g. ['rays','fog','bokeh','zoom','diffuse']
    },
    pxW: 0,
    pxH: 0,
    cssW: 0,
    cssH: 0,
    dpr: 1,
    draws: 0, //       frames actually rendered — an honest fps source
    offscreen: false,
    t0: performance.now(),
  };

  // --- framebuffers: 2 full-res + 2 half-res + 2 quarter-res --------------
  const targets = {}; // name → {tex, fbo, w, h}

  function makeTarget(name, w, h) {
    if (targets[name]) {
      gl.deleteTexture(targets[name].tex);
      gl.deleteFramebuffer(targets[name].fbo);
    }
    const tex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    const fbo = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
    targets[name] = { tex, fbo, w, h };
  }

  function allocTargets() {
    const W = state.pxW, H = state.pxH;
    const hw = Math.max(1, W >> 1), hh = Math.max(1, H >> 1);
    const qw = Math.max(1, W >> 2), qh = Math.max(1, H >> 2);
    makeTarget('fullA', W, H);
    makeTarget('fullB', W, H);
    makeTarget('halfA', hw, hh);
    makeTarget('halfB', hw, hh);
    makeTarget('quarterA', qw, qh);
    makeTarget('quarterB', qw, qh);
    makeTarget('quarterC', qw, qh); // the fog field lives here per frame
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  // --- pass plumbing ------------------------------------------------------
  function bindTex(unit, tex) {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, tex);
  }

  function pass(program, target, setup) {
    const t = target ? targets[target] : null;
    gl.bindFramebuffer(gl.FRAMEBUFFER, t ? t.fbo : null);
    const w = t ? t.w : state.pxW;
    const h = t ? t.h : state.pxH;
    gl.viewport(0, 0, w, h);
    gl.useProgram(program.p);
    if (program.u.uRes) gl.uniform2f(program.u.uRes, w, h);
    setup(program.u, w, h);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  const fx = () => state.effects;
  const stackActive = () =>
    ['fog', 'bokeh', 'rays', 'zoom', 'diffuse', 'grain', 'tint'].some((k) => fx()[k] > 0);

  function drawScene(target, mode) {
    const f = state.formation;
    const [vw, vh] = f.view || [f.w, f.h];
    pass(prg.scene, target, (u) => {
      gl.uniform2f(u.uHalf, vw / 2, vh / 2);
      const flat = new Float32Array(24);
      const n = Math.min(state.current.length, 8);
      for (let i = 0; i < n; i++) {
        flat[i * 3] = state.current[i][0];
        flat[i * 3 + 1] = state.current[i][1];
        flat[i * 3 + 2] = f.r;
      }
      gl.uniform3fv(u.uDots, flat);
      gl.uniform1i(u.uCount, n);
      gl.uniform4fv(u.uInk, state.ink);
      gl.uniform4fv(u.uBg, state.bg);
      gl.uniform1f(u.uMode, mode);
      gl.uniform1f(u.uGrid, state.gridOn ? 1 : 0);
      const ap = state.appearance;
      gl.uniform1f(u.uInkAlpha, ap.opacity ?? 1);
      gl.uniform1i(u.uBlend, BLEND_IDS[ap.blend] ?? 0);
      gl.uniform1f(u.uSoft, ap.soft ?? 0);
      gl.uniform1f(u.uFuse, ap.fuse ?? 0);
      bgUniforms(u);
    });
  }

  // the canvas is a transparent dot layer unless an explicit background was
  // handed to it — blending against the page happens in CSS whenever the
  // canvas doesn't own the ground
  function syncCssBlend() {
    const ap = state.appearance;
    const ownsGround = stackActive() && !!state.effects.background;
    canvas.style.mixBlendMode =
      !ownsGround && ap.blend && ap.blend !== 'normal' ? ap.blend : '';
  }

  function draw() {
    if (!state.formation || !state.pxW) return;
    state.draws++;
    if (!stackActive()) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, state.pxW, state.pxH);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      drawScene(null, 0);
      return;
    }

    const e = fx();
    const time = state.reduced
      ? 0
      : ((performance.now() - state.t0) / 1000) * 0.05 * (e.fogSpeed ?? 0.2);

    // with an explicit background the canvas owns the ground (opaque);
    // otherwise the whole chain runs transparent and CSS composites it
    const ownsGround = !!e.background;
    drawScene('fullA', ownsGround ? 1 : 0);
    let cur = 'fullA'; // name of the current full-res composite
    let spare = 'fullB';
    const swap = () => {
      [cur, spare] = [spare, cur];
    };

    // each pass is a named stage; e.order rearranges the chain freely
    const stages = {
      // fog — the dots' own light (coverage on black, quarter res) gets a
      // field-modulated exponential blur; the composite pushes pixels toward
      // the ink under the fbm mask. The field itself renders once per frame.
      fog: () => {
        if (!(e.fog > 0 || e.grain > 0)) return;
        pass(prg.field, 'quarterC', (u) => gl.uniform1f(u.uTime, time));
        drawScene('quarterA', 2);
        for (const [src, dst, dx, dy] of [
          ['quarterA', 'quarterB', 1, 0],
          ['quarterB', 'quarterA', 0, 1],
        ])
          pass(prg.fogBlur, dst, (u) => {
            bindTex(0, targets[src].tex);
            bindTex(1, targets.quarterC.tex);
            gl.uniform1i(u.uTex, 0);
            gl.uniform1i(u.uField, 1);
            gl.uniform2f(u.uDir, dx, dy);
            gl.uniform1f(u.uAmt, Math.max(e.fog, 0.001));
          });
        pass(prg.fogComp, spare, (u) => {
          bindTex(0, targets[cur].tex);
          bindTex(1, targets.quarterA.tex);
          bindTex(2, targets.quarterC.tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1i(u.uBlur, 1);
          gl.uniform1i(u.uField, 2);
          gl.uniform1f(u.uTime, time);
          gl.uniform1f(u.uFog, e.fog);
          gl.uniform1f(u.uGrain, e.grain);
          gl.uniform1f(u.uOverlay, ownsGround ? 0 : 1);
          gl.uniform4fv(u.uInk, state.ink);
          gl.uniform4fv(u.uBg, state.bg);
          bgUniforms(u);
        });
        swap();
      },
      // bokeh — golden-angle disc blur at half res; replaces the frame
      bokeh: () => {
        if (!(e.bokeh > 0)) return;
        pass(prg.bokeh, 'halfA', (u) => {
          bindTex(0, targets[cur].tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1f(u.uAmt, e.bokeh);
        });
        pass(prg.grade, spare, (u) => {
          bindTex(0, targets.halfA.tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1f(u.uTintAmt, 0);
          gl.uniform3f(u.uTintInk, 0, 0, 0);
          gl.uniform3f(u.uTintBg, 0, 0, 0);
        });
        swap();
      },
      // god rays — half-res march toward the light, added over the frame
      rays: () => {
        if (!(e.rays > 0)) return;
        pass(prg.rays, 'halfB', (u) => {
          bindTex(0, targets[cur].tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1f(u.uAmt, e.rays);
        });
        pass(prg.add, spare, (u) => {
          bindTex(0, targets[cur].tex);
          bindTex(1, targets.halfB.tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1i(u.uAddT, 1);
        });
        swap();
      },
      // zoom blur — radial streaks, gated off near the center
      zoom: () => {
        if (!(e.zoom > 0)) return;
        pass(prg.zoom, spare, (u) => {
          bindTex(0, targets[cur].tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1f(u.uAmt, e.zoom);
        });
        swap();
      },
      // diffuse — static scatter, sharp center / dissolved edges
      diffuse: () => {
        if (!(e.diffuse > 0)) return;
        pass(prg.diffuse, spare, (u) => {
          bindTex(0, targets[cur].tex);
          gl.uniform1i(u.uTex, 0);
          gl.uniform1f(u.uAmt, e.diffuse);
          gl.uniform1f(u.uDifAngle, ((e.difAngle ?? 45) * Math.PI) / 180);
          gl.uniform1f(u.uDifTight, e.difTight ?? 0.75);
        });
        swap();
      },
    };
    const order =
      Array.isArray(e.order) && e.order.length
        ? e.order
        : ['fog', 'bokeh', 'rays', 'zoom', 'diffuse'];
    for (const name of order) stages[name]?.();

    // grade to screen (duotone tint for non-B&W colorways, or plain blit)
    pass(prg.grade, null, (u) => {
      bindTex(0, targets[cur].tex);
      gl.uniform1i(u.uTex, 0);
      gl.uniform1f(u.uTintAmt, e.tint);
      const tc = parseColor(e.tintColor);
      gl.uniform3f(u.uTintInk, tc[0], tc[1], tc[2]);
      gl.uniform3f(u.uTintBg, state.bg[0], state.bg[1], state.bg[2]);
    });
  }

  // --- loop ---------------------------------------------------------------
  const needsLoop = () =>
    !state.offscreen &&
    (!!state.anims || (!state.reduced && (fx().fog > 0 || fx().grain > 0)));

  function tick(now) {
    state.raf = 0;
    if (state.anims) {
      const { pts, live } = sampleTweens(state.anims, now, state.easing);
      state.current = pts;
      if (!live) {
        state.anims = null;
        state.onSettle?.();
      }
    }
    draw();
    if (needsLoop()) state.raf = requestAnimationFrame(tick);
  }

  function ensureLoop() {
    if (!state.raf && needsLoop()) state.raf = requestAnimationFrame(tick);
  }

  // canvas backing size = css × dpr (capped 2) × renderScale — the whole
  // chain scales with it, so renderScale is the master performance lever
  function applySize() {
    if (!state.cssW) return;
    const scale =
      Math.min(state.dpr, 2) * Math.max(0.25, Math.min(1, state.effects.renderScale || 1));
    const w = Math.max(1, Math.round(state.cssW * scale));
    const h = Math.max(1, Math.round(state.cssH * scale));
    if (w === state.pxW && h === state.pxH) return;
    state.pxW = w;
    state.pxH = h;
    canvas.width = w;
    canvas.height = h;
    allocTargets();
    draw();
  }

  function readColors() {
    if (typeof getComputedStyle !== 'function') return;
    const cs = getComputedStyle(host);
    state.ink = state.appearance.ink
      ? parseColor(state.appearance.ink)
      : parseColor(cs.color);
    const b = state.effects.background;
    // ground may be a vertical 3-stop gradient: { gradient: [[pos, color] ×3] }
    if (b && typeof b === 'object' && Array.isArray(b.gradient) && b.gradient.length >= 3) {
      state.bgGrad = {
        mid: b.gradient[1][0],
        stops: b.gradient.slice(0, 3).map((s) => parseColor(s[1])),
      };
      state.bg = state.bgGrad.stops[1];
      return;
    }
    state.bgGrad = null;
    const bgStr =
      (typeof b === 'string' && b) ||
      (() => {
        let el = host;
        while (el) {
          const c = getComputedStyle(el).backgroundColor;
          if (c && !c.startsWith('rgba(0, 0, 0, 0)')) return c;
          el = el.parentElement;
        }
        return document.body ? getComputedStyle(document.body).backgroundColor : '#fff';
      })();
    state.bg = parseColor(bgStr);
  }

  function bgUniforms(u) {
    if (u.uBgMode === undefined) return;
    gl.uniform1f(u.uBgMode, state.bgGrad ? 1 : 0);
    const flat = new Float32Array(9);
    if (state.bgGrad)
      for (let i = 0; i < 3; i++) {
        flat[i * 3] = state.bgGrad.stops[i][0];
        flat[i * 3 + 1] = state.bgGrad.stops[i][1];
        flat[i * 3 + 2] = state.bgGrad.stops[i][2];
      }
    gl.uniform3fv(u.uBgStops, flat);
    gl.uniform1f(u.uBgMid, state.bgGrad ? state.bgGrad.mid : 0.5);
  }

  readColors();

  return {
    setFormation(f, { animate = true } = {}) {
      const first = !state.formation;
      state.formation = f;
      readColors();
      const instant =
        first ||
        !animate ||
        state.reduced ||
        state.motion === 'instant' ||
        state.duration <= 0;
      const targetDots = first ? f.dots : assignTargets(state.current, f.dots);
      if (instant) {
        state.anims = null;
        state.current = targetDots.map((d) => d.slice());
        draw();
        state.onSettle?.();
      } else {
        state.anims = buildTweens(state.current, targetDots, state, performance.now());
      }
      ensureLoop();
    },
    showGrid(on) {
      state.gridOn = !!on;
      draw();
    },
    configure(patch) {
      Object.assign(state, patch);
      readColors();
      draw();
    },
    setEffects(patch) {
      const prevScale = state.effects.renderScale;
      Object.assign(state.effects, patch);
      readColors();
      syncCssBlend();
      if (state.effects.renderScale !== prevScale) applySize();
      draw();
      ensureLoop();
    },
    /** Dot layer look: { ink, opacity, blend, soft }. */
    setAppearance(patch) {
      Object.assign(state.appearance, patch);
      readColors();
      syncCssBlend();
      draw();
    },
    refreshInk() {
      readColors();
      draw();
    },
    /** Set positions immediately (dragging) — cancels any running tween. */
    poke(dots) {
      state.anims = null;
      state.current = dots.map((d) => d.slice());
      draw();
    },
    get current() {
      return state.current.map((d) => d.slice());
    },
    resizePx(cssW, cssH, dpr) {
      state.cssW = cssW;
      state.cssH = cssH;
      state.dpr = dpr || 1;
      applySize();
    },
    /** Pause rendering entirely while scrolled out of view. */
    setVisible(v) {
      state.offscreen = !v;
      if (v) {
        draw();
        ensureLoop();
      } else if (state.raf) {
        cancelAnimationFrame(state.raf);
        state.raf = 0;
      }
    },
    get draws() {
      return state.draws;
    },
    get formation() {
      return state.formation;
    },
    get settled() {
      return !state.anims;
    },
    set onSettle(fn) {
      state.onSettle = fn;
    },
    destroy() {
      if (state.raf) cancelAnimationFrame(state.raf);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

// ---- src/element.js ----
// kzn-logo — <kzn-logo> custom element. Framework-agnostic: drop the script on
// any page (plain HTML, React, Vue, ...) and use the tag.
//
//   <kzn-logo mode="static"></kzn-logo>                     the stable symbol
//   <kzn-logo mode="dynamic" interactive seed="kzn"></kzn-logo>
//
// Sizing is the host's business (CSS width/height); ink is CSS `color`.




const BASE_CELLS = 4; // cells on the short side — the 4×4 heritage

class KznLogo extends HTMLElement {
  static observedAttributes = ['mode', 'seed', 'grid', 'interactive', 'renderer', 'drag'];

  #svg = null;
  #canvas = null;
  #dyn = null;
  #ro = null;
  #dims = null; // { w, h, vw, vh } — generation and view dims, in cells
  #base = null; // seed base
  #step = 0; //   0 = the ideal mark; n>0 = generated formation n
  #engineOpts = {};
  #effectsOpts = null;
  #appearanceOpts = null;
  #intro = null; // authored opening formation — see the `intro` setter
  #px = null; //   last measured host size in CSS px
  #io = null;
  #scale = 1; // grid zoom: 1 = four cells on the short side (the default web size)
  #resizeTimer = 0;

  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    const style = document.createElement('style');
    style.textContent =
      ':host{display:block;color:inherit}:host([interactive]){cursor:pointer}' +
      ':host([drag]){touch-action:none}' +
      'svg,canvas{display:block;width:100%;height:100%}' +
      '[hidden]{display:none !important}';
    this.#svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    this.#svg.setAttribute('aria-hidden', 'true');
    root.append(style, this.#svg);
  }

  connectedCallback() {
    if (!this.hasAttribute('role')) this.setAttribute('role', 'img');
    if (!this.hasAttribute('aria-label'))
      this.setAttribute('aria-label', 'Kaizen logo');
    this.#base = this.getAttribute('seed') || Math.random().toString(36).slice(2, 8);
    if (this.hasAttribute('interactive')) this.setAttribute('tabindex', '0');
    this.addEventListener('click', this.#onClick);
    this.addEventListener('keydown', this.#onKey);
    this.addEventListener('pointerdown', this.#onPointerDown);
    this.addEventListener('pointermove', this.#onPointerMove);
    this.addEventListener('pointerup', this.#onPointerEnd);
    this.addEventListener('pointercancel', this.#onPointerEnd);
    this.#mount();
  }

  disconnectedCallback() {
    this.removeEventListener('click', this.#onClick);
    this.removeEventListener('keydown', this.#onKey);
    this.removeEventListener('pointerdown', this.#onPointerDown);
    this.removeEventListener('pointermove', this.#onPointerMove);
    this.removeEventListener('pointerup', this.#onPointerEnd);
    this.removeEventListener('pointercancel', this.#onPointerEnd);
    this.#unmount();
  }

  attributeChangedCallback(name, oldV, newV) {
    if (oldV === newV || !this.isConnected) return;
    if (name === 'mode') this.#mount();
    else if (name === 'seed') {
      this.#base = newV || this.#base;
      this.#step = 0;
      this.#apply(true);
    } else if (name === 'grid') this.#dyn?.showGrid(newV !== null);
    else if (name === 'renderer') this.#mount();
    else if (name === 'interactive') {
      if (newV !== null) this.setAttribute('tabindex', '0');
      else this.removeAttribute('tabindex');
    }
  }

  get mode() {
    return this.getAttribute('mode') === 'dynamic' ? 'dynamic' : 'static';
  }

  /** Engine + motion options; merged, live. See core.defaults and svg renderer. */
  set options(patch) {
    const motion = {};
    for (const k of ['duration', 'stagger', 'easing', 'motion'])
      if (k in patch) motion[k] = patch[k];
    for (const k of ['placement', 'gap', 'spread', 'edge', 'rankStep', 'count', 'rollouts'])
      if (k in patch) this.#engineOpts[k] = patch[k];
    this.#dyn?.configure(motion);
    let dirty = Object.keys(patch).some((k) => k in this.#engineOpts) && this.#step > 0;
    if ('scale' in patch && patch.scale !== this.#scale) {
      this.#scale = Math.max(0.25, Math.min(8, +patch.scale || 1));
      if (this.#dims) {
        this.#dims = this.#computeDims(this.#dims.vw / this.#dims.vh);
        dirty = true;
      }
    }
    if (dirty) this.#apply(true);
  }

  /** Advance to the next formation (or restart from a given seed). */
  shuffle(seed) {
    if (this.mode !== 'dynamic') return;
    if (seed !== undefined) {
      this.#base = String(seed);
      this.#step = 1;
    } else this.#step++;
    this.#apply(true);
  }

  /** Back to the resting state: the ideal mark on the current canvas. */
  rest() {
    this.#step = 0;
    this.#apply(true);
  }

  /**
   * Post-effect parameters (WebGL renderer only; ignored by SVG):
   * { blur: px, grain: 0..1, tint: 0..1, tintColor: '#…', background: '#…' }.
   * All zero by default — flat parity. Placeholder stack until the Unicorn
   * Studio effect chain is replicated.
   */
  set effects(patch) {
    this.#effectsOpts = { ...(this.#effectsOpts || {}), ...patch };
    this.#dyn?.setEffects?.(this.#effectsOpts);
  }

  get effects() {
    return this.#effectsOpts;
  }

  /** Re-read CSS ink/ground colors (call after a theme change). */
  refreshInk() {
    this.#dyn?.refreshInk?.();
  }

  /** Frames actually rendered so far (webgl) — for honest fps readouts. */
  get draws() {
    return this.#dyn?.draws ?? 0;
  }

  /**
   * Dot layer look, both renderers: { ink: '#…', opacity: 0..1,
   * blend: 'normal'|'difference'|'multiply'|'screen', soft: cells }.
   * (The hero comp: Signal #FEA021, opacity 0.1, difference, heavy soft.)
   */
  set appearance(patch) {
    this.#appearanceOpts = { ...(this.#appearanceOpts || {}), ...patch };
    this.#dyn?.setAppearance?.(this.#appearanceOpts);
  }

  get appearance() {
    return this.#appearanceOpts;
  }

  /**
   * Authored opening formation (kernel first), shown at step 0 instead of
   * the ideal mark. Two anchorings:
   *  · { r, dots } — viewport fractions (r of viewport height)
   *  · { insets: [top, right, bottom, left] px, r, dots } — dots are
   *    fractions of the inset box, r a fraction of the box height; the px
   *    insets stay FIXED under resize, like real page padding
   * Every shuffle leaves it for engine-generated constellations solved for
   * the live window — independent of the authored opening.
   */
  set intro(v) {
    this.#intro = v;
    if (this.#step === 0) this.#apply(false);
  }

  get intro() {
    return this.#intro;
  }

  get formation() {
    return this.mode === 'dynamic' ? this.#dyn?.formation : MARK;
  }

  get seed() {
    if (this.#customDrag) return 'custom';
    return this.#step === 0 ? 'mark' : `${this.#base}#${this.#step}`;
  }

  /** Standalone SVG markup of what is currently shown (for export). */
  exportSVG(opts) {
    const f = this.mode === 'dynamic' ? this.#dyn?.formation : MARK;
    return toSVG(f || MARK, opts);
  }

  // --- internals ---------------------------------------------------------

  #dragState = null; // { index, moved, x0, y0 } while a pointer holds a dot
  #suppressClick = false;
  #customDrag = false;

  #onClick = () => {
    if (this.#suppressClick) {
      this.#suppressClick = false;
      return;
    }
    if (this.hasAttribute('interactive')) this.shuffle();
  };

  #onKey = (e) => {
    if (!this.hasAttribute('interactive')) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      this.shuffle();
    }
  };

  // --- dragging: dots move under the rules -------------------------------

  #cellFromEvent(e) {
    const rect = this.getBoundingClientRect();
    const { vw, vh } = this.#dims;
    return [
      ((e.clientX - rect.left) / rect.width - 0.5) * vw,
      ((e.clientY - rect.top) / rect.height - 0.5) * vh,
    ];
  }

  #hitDot(p) {
    const f = this.#dyn?.formation;
    if (!f) return -1;
    const cur = this.#dyn.current;
    let best = -1;
    let bestD = Infinity;
    for (let i = 0; i < cur.length; i++) {
      const d = Math.hypot(p[0] - cur[i][0], p[1] - cur[i][1]);
      if (d <= f.r * 1.2 && d < bestD) {
        best = i;
        bestD = d;
      }
    }
    return best;
  }

  #dragReady() {
    return (
      this.hasAttribute('drag') && this.mode === 'dynamic' && this.#dyn && this.#dims
    );
  }

  #onPointerDown = (e) => {
    this.#suppressClick = false; // a fresh interaction always starts clean
    if (!this.#dragReady() || !e.isPrimary) return;
    const cell = this.#cellFromEvent(e);
    const i = this.#hitDot(cell);
    if (i < 0) return;
    this.setPointerCapture(e.pointerId);
    const dot = this.#dyn.current[i];
    this.#dragState = {
      index: i,
      moved: false,
      x0: e.clientX,
      y0: e.clientY,
      // keep the grab point — the dot must not jump to the pointer center
      off: [dot[0] - cell[0], dot[1] - cell[1]],
    };
  };

  #onPointerMove = (e) => {
    if (!this.#dragReady()) return;
    if (!this.#dragState) {
      if (this.hasAttribute('drag'))
        this.style.cursor =
          this.#hitDot(this.#cellFromEvent(e)) >= 0
            ? 'grab'
            : this.hasAttribute('interactive')
              ? 'pointer'
              : '';
      return;
    }
    const s = this.#dragState;
    if (!s.moved && Math.hypot(e.clientX - s.x0, e.clientY - s.y0) < 3) return;
    s.moved = true;
    this.style.cursor = 'grabbing';
    const f = this.#dyn.formation;
    const cur = this.#dyn.current;
    const cell = this.#cellFromEvent(e);
    // free drag by default; drag="grid" restores lattice-constrained moves
    // (where the kernel orbits and takes the raw pointer as its direction)
    const grid = this.getAttribute('drag') === 'grid';
    const target =
      grid && s.index === 0
        ? cell
        : [cell[0] + s.off[0], cell[1] + s.off[1]];
    cur[s.index] = (grid ? constrainDrag : freeDrag)(
      { w: f.w, h: f.h, dots: cur },
      s.index,
      target,
      this.#engineOpts
    );
    this.#dyn.poke(cur);
  };

  #onPointerEnd = (e) => {
    const s = this.#dragState;
    if (!s) return;
    this.#dragState = null;
    if (this.hasPointerCapture?.(e.pointerId)) this.releasePointerCapture(e.pointerId);
    this.style.cursor = '';
    if (!s.moved) return; // a plain tap — let click-to-shuffle handle it
    this.#suppressClick = true;
    const f = this.#dyn.formation;
    f.dots = this.#dyn.current;
    this.#customDrag = true;
    this.dispatchEvent(
      new CustomEvent('kzn-drag', {
        bubbles: true,
        composed: true,
        detail: { formation: f, index: s.index },
      })
    );
  };

  #mount() {
    this.#unmount();
    if (this.mode === 'static') {
      this.#svg.toggleAttribute('hidden', false);
      renderMark(this.#svg);
      return;
    }
    // dynamic: WebGL when asked for and available, flat SVG otherwise.
    // A fresh canvas per mount — a lost/destroyed context can't be revived.
    if (this.getAttribute('renderer') === 'webgl') {
      this.#canvas = document.createElement('canvas');
      this.#canvas.setAttribute('aria-hidden', 'true');
      this.shadowRoot.append(this.#canvas);
      try {
        this.#dyn = createWebGLRenderer(this.#canvas, this);
      } catch {
        this.#dyn = null;
      }
      if (!this.#dyn) {
        this.#canvas.remove();
        this.#canvas = null;
      }
    }
    const usingGL = !!this.#dyn;
    if (!usingGL) this.#dyn = createDynamicRenderer(this.#svg);
    this.#svg.toggleAttribute('hidden', usingGL);
    this.dataset.rendererActive = usingGL ? 'webgl' : 'svg';
    if (usingGL && this.#effectsOpts) this.#dyn.setEffects(this.#effectsOpts);
    if (this.#appearanceOpts) this.#dyn.setAppearance?.(this.#appearanceOpts);

    this.#dyn.onSettle = () =>
      this.dispatchEvent(
        new CustomEvent('kzn-settle', { bubbles: true, composed: true })
      );
    this.#ro = new ResizeObserver((entries) => {
      const r = entries[entries.length - 1].contentRect;
      if (r.width < 1 || r.height < 1) return;
      this.#dyn?.resizePx?.(r.width, r.height, window.devicePixelRatio || 1);
      this.#px = { w: r.width, h: r.height };
      const prev = this.#dims;
      this.#dims = this.#computeDims(r.width / r.height);
      const d = this.#dims;
      if (!prev) {
        this.#apply(false); // first layout: paint instantly
      } else if (
        Math.abs(prev.w - d.w) > 0.02 ||
        Math.abs(prev.h - d.h) > 0.02 ||
        Math.abs(prev.vw - d.vw) > 0.02 ||
        Math.abs(prev.vh - d.vh) > 0.02
      ) {
        clearTimeout(this.#resizeTimer);
        this.#resizeTimer = setTimeout(() => this.#apply(true), 90);
      }
    });
    this.#ro.observe(this);
    // scrolled out of view → the renderer stops burning frames entirely
    this.#io = new IntersectionObserver((entries) =>
      this.#dyn?.setVisible?.(entries[entries.length - 1].isIntersecting)
    );
    this.#io.observe(this);
  }

  /**
   * Grid zoom. The view always shows 4/scale cells on its short side; the
   * formation is generated on at least the standard 4-cell canvas, so
   * zooming IN (scale > 1) is a pure window — dots grow and bleed off the
   * edges — while zooming OUT (scale < 1) extends the grid and lets the
   * dots re-spread across it. Rules and the 0.775 dot-to-cell ratio hold
   * at every zoom.
   */
  #computeDims(ar) {
    const visShort = BASE_CELLS / this.#scale;
    const genShort = Math.max(BASE_CELLS, visShort);
    const wide = ar >= 1;
    return {
      w: wide ? genShort * ar : genShort,
      h: wide ? genShort : genShort / ar,
      vw: wide ? visShort * ar : visShort,
      vh: wide ? visShort : visShort / ar,
    };
  }

  #unmount() {
    this.#ro?.disconnect();
    this.#ro = null;
    this.#io?.disconnect();
    this.#io = null;
    clearTimeout(this.#resizeTimer);
    this.#dyn?.destroy();
    this.#dyn = null;
    this.#dims = null;
    this.#svg.textContent = '';
    this.#canvas?.remove();
    this.#canvas = null;
    delete this.dataset.rendererActive;
  }

  #formationForStep() {
    const { w, h, vw, vh } = this.#dims;
    let f;
    if (this.#step === 0 && this.#intro) {
      const it = this.#intro;
      if (it.insets && this.#px) {
        // fixed px insets; the formation lives inside the box (the comp's
        // anchoring: 138px sides, 53px top, 130px bottom at base)
        const [t, ri, b, l] = it.insets;
        const { w: pxW, h: pxH } = this.#px;
        const bw = Math.max(1, pxW - l - ri);
        const bh = Math.max(1, pxH - t - b);
        let rPx;
        let dotsPx;
        if (it.fit === 'mark') {
          // the ideal mark fitted so its tight bbox IS the box: vertical
          // rhythm canonical (box height = (2 + R) vertical cells, dot
          // radius 0.3875 of a cell), columns spread to fill the width
          const cellY = bh / (2 + R);
          rPx = R * cellY;
          dotsPx = [
            [bw / 2, rPx + cellY], // kernel — tangent under the box's crosshair
            [bw / 2, rPx],
            [rPx, rPx],
            [bw - rPx, rPx],
            [rPx, bh - rPx],
            [bw - rPx, bh - rPx],
          ];
        } else {
          rPx = it.r * bh;
          dotsPx = it.dots.map(([bx, by]) => [bx * bw, by * bh]);
        }
        f = {
          w,
          h,
          r: rPx / (pxH / vh),
          seed: 'intro',
          dots: dotsPx.map(([dx, dy]) => [
            ((l + dx) / pxW - 0.5) * vw,
            ((t + dy) / pxH - 0.5) * vh,
          ]),
          lines: null,
        };
      } else {
        // viewport-proportional anchoring
        f = {
          w,
          h,
          r: it.r * vh,
          seed: 'intro',
          dots: it.dots.map(([fx, fy]) => [(fx - 0.5) * vw, (fy - 0.5) * vh]),
          lines: null,
        };
      }
    } else if (this.#step === 0) {
      f = {
        w,
        h,
        r: R,
        seed: 'mark',
        dots: MARK_IDEAL.dots.map((d) => d.slice()),
        lines: null,
      };
    } else {
      // steer away from where the dots already sit, so every shuffle
      // genuinely relocates (no dot camping in its corner for five clicks)
      f = generate(w, h, `${this.#base}#${this.#step}`, {
        ...this.#engineOpts,
        avoid: this.#dyn?.formation?.dots || null,
      });
    }
    // the view may be a window into (zoom in) or an extension of (zoom out)
    // the generation canvas; gridlines cover whichever is larger
    f.view = [vw, vh];
    f.lines = gridLines(Math.max(w, vw), Math.max(h, vh));
    return f;
  }

  #apply(animate) {
    if (this.mode !== 'dynamic' || !this.#dyn || !this.#dims) return;
    this.#customDrag = false;
    const f = this.#formationForStep();
    this.#dyn.setFormation(f, { animate });
    this.#dyn.showGrid(this.hasAttribute('grid'));
    this.dispatchEvent(
      new CustomEvent('kzn-shuffle', {
        bubbles: true,
        composed: true,
        detail: { formation: f, step: this.#step, seed: this.seed },
      })
    );
  }
}

if (!customElements.get('kzn-logo')) customElements.define('kzn-logo', KznLogo);
